/* One shared SVG coordinate system. Dragging changes display geometry only. */
(function(){'use strict';
let data,catalog,helpers,api;const S={node:null,edge:null,section:'lesson',detailOpen:false,evidence:null,query:'',zoom:1,panX:0,panY:0,initialized:false,types:new Set(['within_case','proposed_question','lesson_use','declared_reference','formula_variant']),moved:new Map(),pointers:new Map(),gesture:null,skipClickUntil:0};
const E=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const typeNames={within_case:'가설 → 검토 교훈',proposed_question:'교훈 → 미실행 질문',lesson_use:'명시적 교훈 활용',declared_reference:'명시적 비교·참조',formula_variant:'동일 코드 · 조건 변형',editorial_category:'편집 연관 · 같은 분류'};
const directed=e=>!['formula_variant','editorial_category'].includes(e.type);
const arrow=e=>directed(e)?'→':'↔';
const filterNames={within_case:'가설 → 교훈',proposed_question:'교훈 → 미실행',lesson_use:'기록된 교훈 활용',declared_reference:'명시적 비교',formula_variant:'동일 코드 변형',editorial_category:'분류 연관 · 편집'};
const kinds={hypothesis:'가설',lesson:'교훈',question:'질문 · 미실행'};
const node=id=>data.nodes.find(n=>n.id===id);const row=id=>catalog.records.find(r=>r.record_id===id);const title=r=>helpers.title(r.factor_name);
const pos=n=>S.moved.get(n.id)||{x:n.x,y:n.y};
const visible=e=>S.types.has(e.type);const incident=id=>data.edges.filter(e=>visible(e)&&(e.from===id||e.to===id));
function caseEdges(id){const caseId=node(id).case_id;return data.edges.filter(e=>visible(e)&&(node(e.from).case_id===caseId||node(e.to).case_id===caseId));}
function neighborhood(){const ids=new Set();if(S.edge){const e=data.edges.find(e=>e.id===S.edge);ids.add(e.from).add(e.to);}else{for(const n of data.nodes)if(n.case_id===node(S.node).case_id)ids.add(n.id);for(const e of caseEdges(S.node))ids.add(e.from).add(e.to);}return ids;}
const clip=(s,n=42)=>String(s||'').length>n?String(s).slice(0,n)+'…':String(s||'');
function shape(n){return n.kind==='hypothesis'?'<circle r="10"/>':n.kind==='lesson'?'<rect x="-9" y="-9" width="18" height="18" rx="4"/>':'<path d="M0 -12 12 0 0 12 -12 0Z"/>';}
function edgePath(e){const a=pos(node(e.from)),b=pos(node(e.to));if(e.type==='within_case'||e.type==='proposed_question')return `M${a.x},${a.y} L${b.x},${b.y}`;const dx=b.x-a.x,dy=b.y-a.y,bend=e.type==='lesson_use'?45:Math.min(75,Math.hypot(dx,dy)*.12);return `M${a.x},${a.y} Q${(a.x+b.x)/2-dy/Math.max(1,Math.hypot(dx,dy))*bend},${(a.y+b.y)/2+dx/Math.max(1,Math.hypot(dx,dy))*bend} ${b.x},${b.y}`;}
function graphMarkup(){const near=neighborhood(),matches=searchMatches();return `<svg class="rmn-canvas" role="group" aria-label="전체 공개 연구 네트워크. 방향키로 노드 이동, Enter로 상세, 배경을 드래그하여 이동" viewBox="0 0 1000 730"><defs><marker id="rmn-arrow" viewBox="0 0 10 10" refX="18" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z"/></marker></defs><g class="rmn-world">${data.clusters.map(c=>`<g class="rmn-cluster"><ellipse cx="${c.x+c.width/2}" cy="${c.y+c.height/2}" rx="${c.width/2}" ry="${c.height/2}"/><text x="${c.x+c.width/2}" y="${c.y+20}" text-anchor="middle">${E(c.label)}</text></g>`).join('')}<g class="rmn-edge-layer">${data.edges.map(e=>`<g data-rmn-edge="${E(e.id)}" class="rmn-edge rmn-${e.type} ${visible(e)?'':'is-filtered'} ${e.id===S.edge?'is-selected':near.has(e.from)&&near.has(e.to)?'is-near':'is-muted'}" role="button" tabindex="-1" aria-label="${E(typeNames[e.type])}: cycle ${node(e.from).cycle} ${arrow(e)} ${node(e.to).cycle}"><path class="rmn-line" d="${edgePath(e)}" ${e.type==='lesson_use'?'marker-end="url(#rmn-arrow)"':''}/><path class="rmn-edge-hit" d="${edgePath(e)}"/><title>${E(e.label)} · ${node(e.from).cycle} ${arrow(e)} ${node(e.to).cycle}</title></g>`).join('')}</g><g class="rmn-node-layer">${data.nodes.map(n=>{const p=pos(n),r=row(n.case_id),label=n.kind==='hypothesis'?r.definition.hypothesis:n.kind==='lesson'?r.review.general_lesson:r.review.follow_up.question;return `<g transform="translate(${p.x} ${p.y})" data-rmn-node="${E(n.id)}" class="rmn-node rmn-${n.kind} ${S.node===n.id&&!S.edge?'is-selected':near.has(n.id)?'is-near':'is-muted'} ${matches.has(n.case_id)?'is-match':''}" role="button" tabindex="${n.id===S.node?'0':'-1'}" aria-label="cycle ${n.cycle} ${kinds[n.kind]}: ${E(title(r))}" aria-pressed="${n.id===S.node&&!S.edge}"><circle class="rmn-hit" r="19"/>${shape(n)}<text class="rmn-cycle" y="-21" text-anchor="middle">${n.cycle} · ${kinds[n.kind]}</text><text class="rmn-label" x="0" y="32" text-anchor="middle">${E(clip(title(r),21))}</text><title>${n.cycle} ${kinds[n.kind]} · ${E(label)}</title></g>`;}).join('')}</g></g></svg>`;}
function searchMatches(){const q=S.query.trim().toLowerCase();return new Set(!q?[]:catalog.records.filter(r=>[r.factor_name,title(r),r.provenance.cycle,r.definition.hypothesis,r.review.general_lesson,r.review.follow_up.question].join(' ').toLowerCase().includes(q)).map(r=>r.record_id));}
function searchResults(){const matches=searchMatches();return S.query?`<div class="rmn-search-results" role="status"><small>${matches.size}개 사례 일치 · 다른 노드도 유지합니다</small>${[...matches].slice(0,12).map(id=>{const n=data.nodes.find(n=>n.case_id===id&&n.kind==='lesson');return `<button data-rmn-select="${E(n.id)}">${n.cycle} · ${E(title(row(id)))}</button>`;}).join('')}</div>`:'';}
function panel(){if(S.edge)return edgeDetail(data.edges.find(e=>e.id===S.edge));const n=node(S.node),r=row(n.case_id);const nearEdges=caseEdges(S.node),cross=nearEdges.filter(e=>node(e.from).case_id!==node(e.to).case_id);return `<div class="rmn-panel-top"><span>CYCLE ${n.cycle} · ${kinds[n.kind]}</span><h2>${E(title(r))}</h2><p>${E(window.ResearchSemantics?.researchVerdict(r).label||r.validation.verdict)} · 교훈 ${E(r.review.stance)}<br>원가설 성공·메커니즘 입증과 구분합니다.</p><button class="small-button" data-record="${E(r.record_id)}">기존 연구 상세 ↗</button></div><div class="rmn-tabs">${[['hypothesis','가설'],['lesson','교훈'],['followup','다음 질문'],['observations','관측'],['explanations','대안 설명'],['limits','한계']].map(([key,label])=>`<button data-rmn-section="${key}" aria-pressed="${S.section===key}">${label}</button>`).join('')}</div><div class="rmn-content">${api.detail(r,S.section,S.evidence)}</div><div class="rmn-connections"><h3>선택한 연구의 다른 연구 연결 · ${cross.length}</h3>${cross.map(e=>{const other=node(node(e.from).case_id===n.case_id?e.to:e.from);return `<button data-rmn-edge-select="${E(e.id)}"><span class="rmn-key rmn-${e.type}"></span>${E(typeNames[e.type])}<small>cycle ${other.cycle} · ${E(title(row(other.case_id)))}</small></button>`;}).join('')||'<p>이 연구에서 다른 연구로 이어지는 선택된 유형의 연결 기록이 없습니다. 관계를 임의로 채우지 않습니다.</p>'}<p>미실행 질문은 다음 실험으로 실행된 것처럼 연결하지 않습니다. ${influenceNote()}</p></div>`;}
function registrationDetail(e){const r=e.registration;if(!r)return '';return `<h3>등록 때 보존한 참조</h3><p>캡처 ${E(r.snapshot_captured_at)}<br>선언 ${E(r.declared_at)}<br>등록 ${E(r.registered_at)}</p><p>시각은 로컬 도구의 기록이며 독립 시각 인증은 아닙니다. 읽기·인과 영향·후속 실행을 입증하지 않습니다.</p><details class="rm-source"><summary>보존한 식별자</summary><code>snapshot ${E(r.knowledge_snapshot_hash)}<br>capture ${E(r.capture_id)}<br>declaration ${E(r.declaration_hash)}<br>source review ${E(r.source_review_hash)}</code></details>`;}
function influenceNote(){return data.edges.some(e=>e.registration)?`검증된 교훈 활용 기록 ${data.counts.lesson_use||0}건입니다. 등록 시 선언과 원문 인용은 연결 상세에서 구분합니다.`:'교훈 활용 경로는 229→230의 1건만 확인됩니다.';}
function edgeDetail(e){const a=node(e.from),b=node(e.to);return `<div class="rmn-panel-top"><span>연결의 근거</span><h2>${E(e.label)}</h2><p>${E(e.note)}</p></div><div class="rmn-edge-endpoints">${[a,b].map(n=>`<button data-rmn-select="${E(n.id)}"><small>CYCLE ${n.cycle} · ${kinds[n.kind]}</small><strong>${E(title(row(n.case_id)))}</strong></button>`).join(`<span class="rmn-relation-direction" aria-label="${directed(e)?'원문 관계의 방향':'방향 없는 비교 관계'}">${arrow(e)}</span>`)}</div><div class="rmn-content"><p class="rm-callout">${e.registration?'등록 때 선언한 참조 · 읽기나 인과 영향의 증명은 아닙니다.':e.type==='lesson_use'?'실제 영향의 명시적 기록 · 후속 질문 실행과는 다릅니다.':e.type==='formula_variant'?'코드의 정확한 일치를 계산한 관계 · 사고 계보와는 다릅니다.':e.type==='editorial_category'?'편집상 탐색 연관 · 실증 관계가 아닙니다.':'원문 참조 또는 같은 검토의 구조 · 인과성의 증명이 아닙니다.'}</p>${registrationDetail(e)}${e.quote?`<h3>연결을 확인한 원문</h3><p>${E(e.quote)}</p>`:''}${(e.quotes||[]).map(q=>`<h3>${E(q.field)}</h3><p>${E(q.text)}</p>`).join('')}${e.differences?`<h3>각 실험의 고정 조건과 방향</h3>${e.differences.map(d=>`<h4>${E(title(row(d.case_id)))}</h4><pre>${E(JSON.stringify({params:d.params,predicted_sign:d.predicted_sign},null,2))}</pre>`).join('')}`:''}<h3>정확한 출처</h3>${e.sources.map(s=>{const r=row(s.record_id);return `<details class="rm-source"><summary>${E(title(r))}</summary><code>${E(s.pointer)}<br>packet ${E(s.packet_sha256)}</code><p><a target="_blank" rel="noopener" href="https://github.com/2stshine/factor-research/blob/${E(api.revision)}/${E(r.provenance.packet_path)}">불변 근거 패킷 ↗</a></p><p>${E(sourceValue(s))}</p></details>`;}).join('')}<code>${E(e.basis)}</code></div>`;}
function sourceValue(s){const value=s.pointer.split('/').slice(1).reduce((o,k)=>o?.[k.replaceAll('~1','/').replaceAll('~0','~')],catalog);return typeof value==='string'?value:JSON.stringify(value);}
function render(graph,c,h,callbacks){data=graph.network;catalog=c;helpers=h;api={...callbacks,revision:graph.revision};if(!S.node||!node(S.node)){S.node=data.nodes.filter(n=>n.kind==='lesson').sort((a,b)=>b.cycle-a.cycle)[0].id;}
 const k=data.counts;queueMicrotask(mount);return `<div class="rmn-page"><header class="rmn-heading"><div><span class="rm-eyebrow">ONE SHARED SPACE / 하나의 연구 네트워크</span><h1>연구자의 생각을 잇는 지도</h1><p>cycle ${k.cycle_min}–${k.cycle_max} · 공개 연구 ${k.cases}개를 하나의 좌표공간에 놓았습니다.</p></div><div class="rmn-summary"><strong>${k.hypotheses} + ${k.lessons} + ${k.questions}</strong><span>가설 · 교훈 · 미실행 질문</span><small>기록된 교훈 활용 ${k.lesson_use}건 / 실행된 후속 질문 ${k.followups_executed}건</small></div></header><div class="rmn-notice">${E(graph.as_of)} 정적 스냅샷 · 미공개 ${graph.counts.withheld}건의 내용 제외 · 위치와 선의 밀도는 과학적 확신을 뜻하지 않습니다.</div><div class="rmn-tools"><label class="rmn-search"><span>연구·질문 검색</span><input id="rmn-search" type="search" placeholder="사이클 번호, 이름, 교훈의 단어" value="${E(S.query)}" autocomplete="off">${searchResults()}</label><div class="rmn-zoom-controls"><button data-rmn-fit>전체 보기</button><button data-rmn-zoom="0.8" aria-label="축소">−</button><output class="rmn-zoom-value">${Math.round(S.zoom*100)}%</output><button data-rmn-zoom="1.25" aria-label="확대">+</button><button data-rmn-center>선택으로 이동</button><button data-rmn-reset>위치 리셋</button><button data-rmn-panel-toggle aria-controls="rmn-detail" aria-expanded="${S.detailOpen}">${S.detailOpen?'상세 접기':'선택 상세'}</button></div></div><div class="rmn-filters" aria-label="연결 유형 필터">${Object.entries(typeNames).map(([type,label])=>`<label><input type="checkbox" data-rmn-filter="${type}" ${S.types.has(type)?'checked':''}><span class="rmn-key rmn-${type}"></span>${E(filterNames[type])}<b>${k[type]||0}</b></label>`).join('')}</div><div class="rmn-layout ${S.detailOpen?'has-detail':''}"><div class="rmn-map-column"><div class="rmn-stage" tabindex="-1">${graphMarkup()}<div class="rmn-map-caption"><span>● 가설</span><span>■ 교훈</span><span>◇ 질문 · 미실행</span></div><div class="rmn-minimap" aria-hidden="true"><svg viewBox="0 0 ${data.width} ${data.height}">${data.nodes.filter(n=>n.kind==='lesson').map(n=>`<circle cx="${n.x}" cy="${n.y}" r="11"/>`).join('')}<rect class="rmn-viewbox"/></svg></div><div class="rmn-stage-footer"><b>${data.nodes.length}개 노드 전체 표시</b><span>노드 드래그 · 배경 이동 · 휠/두 손가락 확대</span></div></div><div class="rmn-reading"><strong>생각의 계보와 비교 관계를 구분합니다</strong><p>${data.edges.some(e=>e.registration)?influenceNote():'화살표는 229의 교훈을 230이 실제로 활용한 1건입니다.'} 점선 비교·코드 변형은 검토할 이웃이지, 앞 실험이 뒤 실험을 낳았다는 기록이 아닙니다. 연결되지 않은 연구도 그대로 남깁니다. 확대하면 이름을 읽을 수 있습니다.</p><details><summary>현재 연결의 범위와 생성 규칙</summary><p>명시한 비교·참조 ${k.declared_reference}쌍. 원문 5개 서술 필드의 정확한 factor-name 인용 ${k.reference_mentions}개이며, 등록 선언이 있는 경우 상세에서 따로 표시합니다. 동일 frozen compute source: ${k.formula_groups}그룹, ${k.formula_members}개 연구, ${k.formula_variant}쌍. 코드 일치는 줄바꿈·외곽 공백만 정규화하며 params와 방향은 합치지 않습니다.</p><p>교훈 활용 기록이 없는 연구 ${k.without_recorded_lesson_influence}개. 모든 후속 질문은 PROPOSED_NOT_RUN입니다. category 선은 같은 분류의 시간상 이웃을 잇는 편집 레이어로 기본 해제되어 있습니다. 노드 이동은 화면 위치만 바꾸며 관계·원본을 수정하지 않습니다.</p></details></div></div><aside id="rmn-detail" class="rmn-detail rm-detail" aria-label="선택한 노드 또는 연결 상세" aria-live="polite" ${S.detailOpen?'':'hidden'}><button class="rmn-panel-close" data-rmn-panel-close aria-label="상세 패널 닫기">닫기 ×</button>${panel()}</aside></div></div>`;}
function fit(){const stage=document.querySelector('.rmn-stage');if(!stage)return;const box=stage.getBoundingClientRect();S.zoom=Math.min(box.width/data.width,box.height/data.height)*.91;S.panX=(box.width-data.width*S.zoom)/2;S.panY=(box.height-data.height*S.zoom)/2;S.initialized=true;applyView();}
function applyView(){const stage=document.querySelector('.rmn-stage');if(!stage)return;const box=stage.getBoundingClientRect(),svg=stage.querySelector('svg.rmn-canvas');svg.setAttribute('viewBox',`0 0 ${box.width} ${box.height}`);stage.querySelector('.rmn-world').setAttribute('transform',`translate(${S.panX} ${S.panY}) scale(${S.zoom})`);stage.classList.toggle('is-expanded',S.zoom>.62);stage.classList.toggle('is-detailed',S.zoom>1.05);stage.style.setProperty('--map-scale',S.zoom);const out=document.querySelector('.rmn-zoom-value');if(out)out.textContent=Math.round(S.zoom*100)+'%';const rect=stage.querySelector('.rmn-viewbox');rect.setAttribute('x',-S.panX/S.zoom);rect.setAttribute('y',-S.panY/S.zoom);rect.setAttribute('width',box.width/S.zoom);rect.setAttribute('height',box.height/S.zoom);}
function zoomAt(mult,x,y){const next=Math.max(.14,Math.min(3.5,S.zoom*mult)),wx=(x-S.panX)/S.zoom,wy=(y-S.panY)/S.zoom;S.zoom=next;S.panX=x-wx*next;S.panY=y-wy*next;applyView();}
function center(){const stage=document.querySelector('.rmn-stage'),p=pos(node(S.node)),box=stage.getBoundingClientRect();S.zoom=Math.max(S.zoom,.92);const drawer=S.detailOpen&&box.width>620?Math.min(340,box.width*.43):0;S.panX=(box.width-drawer)/2-p.x*S.zoom;S.panY=box.height/2-p.y*S.zoom;applyView();}
function refresh(){api.update();}
function select(id,move=false){if(!node(id))return;S.node=id;S.edge=null;S.detailOpen=true;S.evidence=null;S.section=({hypothesis:'hypothesis',lesson:'lesson',question:'followup'})[node(id).kind];refresh();if(move)queueMicrotask(center);}
function mount(){const stage=document.querySelector('.rmn-stage');if(!stage||stage.dataset.bound)return;stage.dataset.bound='yes';if(!S.initialized)fit();else applyView();
 stage.addEventListener('wheel',e=>{e.preventDefault();const b=stage.getBoundingClientRect();zoomAt(Math.exp(-e.deltaY*.0018),e.clientX-b.left,e.clientY-b.top);},{passive:false});
 stage.addEventListener('pointerdown',e=>{if(e.button!==0&&e.pointerType!=='touch')return;e.preventDefault();stage.setPointerCapture(e.pointerId);S.pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});const n=e.target.closest('[data-rmn-node]'),edge=e.target.closest('[data-rmn-edge]');if(S.pointers.size===2){const [a,b]=[...S.pointers.values()];S.gesture={kind:'pinch',distance:Math.hypot(a.x-b.x,a.y-b.y),centerX:(a.x+b.x)/2,centerY:(a.y+b.y)/2,moved:true};return;}S.gesture={kind:n?'node':edge?'edge':'pan',id:n?.dataset.rmnNode,edge:edge?.dataset.rmnEdge,lastX:e.clientX,lastY:e.clientY,startX:e.clientX,startY:e.clientY,moved:false};});
 stage.addEventListener('pointermove',e=>{if(!S.pointers.has(e.pointerId)||!S.gesture)return;S.pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});const g=S.gesture;if(S.pointers.size>=2){const [a,b]=[...S.pointers.values()],d=Math.hypot(a.x-b.x,a.y-b.y),x=(a.x+b.x)/2,y=(a.y+b.y)/2,rect=stage.getBoundingClientRect();if(g.kind==='pinch'){S.panX+=x-g.centerX;S.panY+=y-g.centerY;zoomAt(d/Math.max(g.distance,1),x-rect.left,y-rect.top);}S.gesture={kind:'pinch',distance:d,centerX:x,centerY:y,moved:true};return;}
  if(g.kind==='pinch')return;if(Math.hypot(e.clientX-g.startX,e.clientY-g.startY)>5)g.moved=true;if(!g.moved)return;
  const dx=e.clientX-g.lastX,dy=e.clientY-g.lastY;g.lastX=e.clientX;g.lastY=e.clientY;
  if(g.kind==='node'){const n=node(g.id),p=pos(n);S.moved.set(n.id,{x:p.x+dx/S.zoom,y:p.y+dy/S.zoom});const el=[...stage.querySelectorAll('[data-rmn-node]')].find(el=>el.dataset.rmnNode===n.id),p2=pos(n);el.setAttribute('transform',`translate(${p2.x} ${p2.y})`);for(const group of stage.querySelectorAll('[data-rmn-edge]')){const edge=data.edges.find(v=>v.id===group.dataset.rmnEdge);if(edge.from===n.id||edge.to===n.id)for(const line of group.querySelectorAll('path'))line.setAttribute('d',edgePath(edge));}}
  else {S.panX+=dx;S.panY+=dy;applyView();}
 });
 const end=e=>{const g=S.gesture;S.pointers.delete(e.pointerId);if(g?.moved)S.skipClickUntil=Date.now()+350;else if(g?.kind==='node'){S.skipClickUntil=Date.now()+350;select(g.id);}else if(g?.kind==='edge'){S.skipClickUntil=Date.now()+350;S.edge=g.edge;S.detailOpen=true;S.evidence=null;refresh();}if(!S.pointers.size)S.gesture=null;else S.gesture={kind:'pinch',moved:true};};stage.addEventListener('pointerup',end);stage.addEventListener('pointercancel',e=>{S.pointers.delete(e.pointerId);S.skipClickUntil=Date.now()+350;S.gesture=S.pointers.size?{kind:'pinch',moved:true}:null;});
 stage.addEventListener('keydown',e=>{const edge=e.target.closest('[data-rmn-edge]');if(edge&&['Enter',' '].includes(e.key)){e.preventDefault();S.edge=edge.dataset.rmnEdge;S.detailOpen=true;S.evidence=null;refresh();return;}const n=e.target.closest('[data-rmn-node]');if(!n)return;if(['Enter',' '].includes(e.key)){e.preventDefault();const id=n.dataset.rmnNode;select(id);queueMicrotask(()=>{[...document.querySelectorAll('[data-rmn-node]')].find(el=>el.dataset.rmnNode===id)?.focus({preventScroll:true});});return;}if(['ArrowRight','ArrowDown','ArrowLeft','ArrowUp'].includes(e.key)){e.preventDefault();const i=data.nodes.findIndex(v=>v.id===n.dataset.rmnNode),delta=['ArrowRight','ArrowDown'].includes(e.key)?1:-1,id=data.nodes[(i+delta+data.nodes.length)%data.nodes.length].id;select(id);queueMicrotask(()=>{[...document.querySelectorAll('[data-rmn-node]')].find(e=>e.dataset.rmnNode===id)?.focus({preventScroll:true});});}});
}
document.addEventListener('click',e=>{if(!data||!document.querySelector('.rmn-page'))return;const t=e.target.closest('[data-rmn-node],[data-rmn-edge],button');if(!t)return;if(t.closest('.rmn-stage')&&Date.now()<S.skipClickUntil){e.preventDefault();return;}
 if(t.hasAttribute('data-rmn-panel-toggle')||t.hasAttribute('data-rmn-panel-close')){S.detailOpen=t.hasAttribute('data-rmn-panel-close')?false:!S.detailOpen;refresh();queueMicrotask(()=>document.querySelector('[data-rmn-panel-toggle]')?.focus({preventScroll:true}));return;}
 if(t.dataset.rmnNode){select(t.dataset.rmnNode);return;}if(t.dataset.rmnEdge||t.dataset.rmnEdgeSelect){S.edge=t.dataset.rmnEdge||t.dataset.rmnEdgeSelect;S.detailOpen=true;S.evidence=null;refresh();return;}
 if(t.dataset.rmnSelect){select(t.dataset.rmnSelect,true);return;}if(t.dataset.rmnSection){S.section=t.dataset.rmnSection;S.evidence=null;refresh();return;}
 if(t.hasAttribute('data-rmn-fit')){S.detailOpen=false;refresh();queueMicrotask(fit);return;}if(t.hasAttribute('data-rmn-center')){center();return;}if(t.hasAttribute('data-rmn-reset')){S.moved.clear();refresh();queueMicrotask(fit);return;}
 if(t.dataset.rmnZoom){const b=document.querySelector('.rmn-stage').getBoundingClientRect();zoomAt(Number(t.dataset.rmnZoom),b.width/2,b.height/2);return;}
 if(t.dataset.rmEvidence){e.stopImmediatePropagation();S.evidence=t.dataset.rmEvidence;refresh();return;}
 if(t.dataset.rmNode){e.stopImmediatePropagation();S.section=t.dataset.rmNode;S.evidence=null;refresh();return;}
 if(t.dataset.rmRecord){e.stopImmediatePropagation();const n=data.nodes.find(n=>n.case_id===t.dataset.rmRecord&&n.kind==='lesson');if(n)select(n.id,true);}
});
document.addEventListener('input',e=>{if(e.target.id==='rmn-search'){S.query=e.target.value;refresh();queueMicrotask(()=>document.querySelector('#rmn-search')?.focus({preventScroll:true}));}});
document.addEventListener('change',e=>{if(e.target.dataset.rmnFilter){const t=e.target.dataset.rmnFilter;if(e.target.checked)S.types.add(t);else S.types.delete(t);S.edge=null;refresh();}});
window.addEventListener('resize',()=>{if(document.querySelector('.rmn-stage'))applyView();});
window.ResearchNetworkUI={render};
})();

/* Reviewer-only graph projection; no experiment or candidate-generation endpoints. */
(function(){
'use strict';
let graph, failure, catalog, helpers, rerender;
const state={theme:'measurement',record:null,node:'lesson',query:'',filter:'ALL',evidence:null};
const E=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const labels={SUPPORTED:'지지 관측',MIXED:'혼합 근거',UNTESTED:'미검증',NOT_SUPPORTED:'지지되지 않음',SUPPORTS:'교훈과 부합',UNCERTAIN:'판단 유보',CONSISTENT:'일관됨',UNDETERMINED:'미결정',NOT_COLLECTED:'그 실행에서 미수집',PARTIAL:'일부 수집',AVAILABLE:'수집됨'};
const sectionTitles={hypothesis:'왜 만들었는가',observations:'무엇을 관측했는가',lesson:'어떤 교훈을 남겼는가',explanations:'다르게 설명할 수 있는가',limits:'아직 무엇을 모르는가',followup:'다음에 무엇을 물을까'};
const sectionTypes={hypothesis:'사전 가설',observations:'관측 사실',lesson:'검토된 해석',explanations:'사후 대안 설명',limits:'한계 · 미확인',followup:'제안 · 미실행'};
const F=(v,n=4)=>typeof v==='number'&&Number.isFinite(v)?v.toFixed(n):'미수집';
const text=(v)=>Array.isArray(v)?v.join('\n'):typeof v==='object'?JSON.stringify(v,null,2):String(v??'');
const lines=v=>text(v).split('\n').filter(Boolean).map(p=>`<p>${E(p)}</p>`).join('');
const badge=(v)=>`<span class="rm-tag">${E(labels[v]||v)}</span>`;
const name=r=>helpers?.title?helpers.title(r.factor_name):r.factor_name;
const theme=()=>graph.themes.find(t=>t.id===state.theme)||graph.themes[0];
const selected=()=>catalog.records.find(r=>r.record_id===state.record);
const projected=()=>graph.records.find(r=>r.id===state.record);
const nodeFor=id=>graph.nodes.find(n=>n.id===id);
const pointer=(r,p)=>p.replace(/^\/records\/\d+/,'').split('/').slice(1).reduce((a,k)=>a?.[k.replaceAll('~1','/').replaceAll('~0','~')],r);
const url=path=>'https://github.com/2stshine/factor-research/blob/'+graph.revision+'/'+path.split('/').map(encodeURIComponent).join('/');
const period=p=>p?.start?`${p.start} → ${p.end}`:'기간 미수집';
function eligible(){return graph.records.filter(p=>p.themes.includes(state.theme)).map(p=>catalog.records.find(r=>r.record_id===p.id)).filter(r=>r&&[name(r),r.factor_name,r.review.general_lesson,r.review.follow_up.question,r.campaign_id].join(' ').toLowerCase().includes(state.query.toLowerCase())).filter(r=>state.filter==='ALL'||r.review.mechanism_assessment.some(a=>a.link===state.theme&&a.assessment===state.filter)).sort((a,b)=>b.campaign_id.localeCompare(a.campaign_id)||Number(b.provenance.cycle.match(/cycle-(\d+)/)?.[1]||0)-Number(a.provenance.cycle.match(/cycle-(\d+)/)?.[1]||0)||a.record_id.localeCompare(b.record_id));}
function chooseFirst(){const rows=eligible();if(!rows.some(r=>r.record_id===state.record))state.record=rows[0]?.record_id||null;}
function source(r,p){return `<details class="rm-source"><summary>출처와 연결 방식 확인</summary><p>인증된 카탈로그의 필드를 그대로 연결했습니다. 검토 판단은 인과관계 입증이 아닙니다.</p><code>${E(p)}</code><p>packet ${E(r.provenance.packet_sha256)}</p><a href="${url(r.provenance.packet_path)}" target="_blank" rel="noopener">불변 근거 패킷 ↗</a> · <a href="${url(r.provenance.result)}" target="_blank" rel="noopener">실험 기록 ↗</a><br><a href="./data/research-catalog.json" target="_blank" rel="noopener">화면의 원본 카탈로그 ↗</a></details>`;}
function evidenceButton(r,id,relation){return `<button class="rm-evidence" data-rm-evidence="${E(id)}">${relation?'<span>'+E(relation)+'</span>':''}${E(id)} ↗</button>`;}
function refs(r,ids,relation){return `<div class="rm-evidence-list">${ids.map(id=>evidenceButton(r,id,relation)).join('')}</div>`;}
function themeGraph(){return `<div class="rm-overview-graph"><div class="rm-hub"><small>REVIEWED KNOWLEDGE</small><strong>${graph.counts.lessons}</strong><span>교훈을 연결하는 질문</span><small>독립 검증 수가 아닙니다</small></div><div class="rm-about-label">탐색 주제 · about</div><div class="rm-themes">${graph.themes.filter(t=>t.id!=='unclassified'||graph.records.some(r=>r.themes.includes(t.id))).map((t,i)=>{const rows=graph.records.filter(r=>r.themes.includes(t.id));return `<button class="rm-theme ${state.theme===t.id?'is-active':''}" style="--theme:${t.color}" data-rm-theme="${t.id}" aria-pressed="${state.theme===t.id}"><span class="rm-topic-index">0${i+1}</span><strong>${E(t.short)}</strong><small>${rows.length}개 교훈 · 편집 분류</small><span class="rm-theme-arrow">↗</span></button>`;}).join('')}</div></div>`;}
function overview(){const t=theme(),rows=eligible(),counts={};for(const p of graph.records.filter(p=>p.themes.includes(state.theme))){const r=catalog.records.find(r=>r.record_id===p.id),a=r.review.mechanism_assessment.find(a=>a.link===state.theme);if(a)counts[a.assessment]=(counts[a.assessment]||0)+1;}
 return `<div class="rm-question"><div><small>지금 탐색하는 공통 질문</small><h2>${E(t.question)}</h2></div><div class="rm-distribution">${Object.entries(counts).map(([s,n])=>`<span>${E(labels[s])} <b>${n}</b></span>`).join('')}</div></div><p class="rm-caption">서로 다른 가설에 대한 검토 판단의 분포입니다. 지지·미지지 건수는 하나의 가설을 놓고 투표한 결과가 아닙니다.</p><div class="rm-toolbar"><label>교훈 · 질문 검색<input id="rm-search" type="search" value="${E(state.query)}" placeholder="예: 거래활동, 비용, 결측" autocomplete="off"></label><label>질문에 대한 검토<select id="rm-filter"><option value="ALL">전체 판단</option>${['UNTESTED','MIXED','SUPPORTED','NOT_SUPPORTED'].map(v=>`<option value="${v}" ${state.filter===v?'selected':''}>${labels[v]}</option>`).join('')}</select></label><label class="rm-case-select">연결된 교훈 ${rows.length}개<select id="rm-case">${rows.map(r=>`<option value="${E(r.record_id)}" ${r.record_id===state.record?'selected':''}>${E(name(r))} · ${r.provenance.cycle.match(/cycle-\d+/)?.[0]||r.campaign_id}</option>`).join('')||'<option>해당 교훈 없음</option>'}</select></label><div class="rm-sequence"><button data-rm-prev aria-label="이전 교훈" ${rows.findIndex(r=>r.record_id===state.record)<=0?'disabled':''}>←</button><button data-rm-next aria-label="다음 교훈" ${rows.findIndex(r=>r.record_id===state.record)>=rows.length-1?'disabled':''}>→</button></div></div>`;
}
function focusGraph(r){const p=projected(),a=r.review.mechanism_assessment.find(a=>a.link===state.theme),w=graph.windows.find(w=>p.windows.includes(w.id)&&w.phase==='discovery');return `<div class="rm-case-heading"><div><span class="rm-eyebrow">SELECTED RESEARCH / ${E(r.provenance.cycle.match(/cycle-\d+/)?.[0])}</span><h2>${E(name(r))}</h2><p>${E(r.campaign_id)} · ${E(window.ResearchSemantics?.researchVerdict(r).label||r.validation.verdict)} ${badge(r.review.stance)}</p></div><button class="small-button" data-record="${E(r.record_id)}">기존 연구 상세 ↗</button></div>${a?`<div class="rm-assessment">${badge(a.assessment)}<p>${E(a.reason||'이 항목에는 별도 이유 문장이 저장되지 않았습니다. 아래 관측·교훈·한계와 원문 근거를 함께 확인하세요.')}</p></div>`:''}<div class="rm-focus-layout"><div><div class="rm-focus-graph" aria-label="선택 연구의 가설, 관측, 해석과 다음 질문"><svg viewBox="0 0 650 460" preserveAspectRatio="none" aria-hidden="true"><path d="M106 109 H545 M106 109 V348 H545 M325 109 V348 M545 109 V348"/></svg><span class="rm-edge-label rm-edge-one">검토의 동기</span><span class="rm-edge-label rm-edge-two">같은 기록의 해석 · 인과 입증 아님</span><span class="rm-edge-label rm-edge-three">확인 필요</span>${['hypothesis','observations','lesson','explanations','limits','followup'].map((key,i)=>`<button class="rm-node rm-node-${key} ${state.node===key&&!state.evidence?'is-selected':''}" data-rm-node="${key}" aria-pressed="${state.node===key&&!state.evidence}"><span>${sectionTypes[key]}</span><strong>${sectionTitles[key]}</strong><small>${key==='hypothesis'?E(r.definition.hypothesis):key==='observations'?`${r.review.observations.length}개 관측 · 출처 연결`:key==='lesson'?E(r.review.general_lesson):key==='explanations'?`${r.review.explanations.length}개 대안 · 지지/제약 근거`:key==='limits'?`${r.review.unresolved.length}개 한계 · 수집 여부 구분`:'PROPOSED_NOT_RUN · 아직 실행 안 함'}</small><b>0${i+1} ↗</b></button>`).join('')}</div><div class="rm-window-note"><strong>같은 달력을 공유하는 연구</strong><p>이 탐색 기간 ${period(w)}을 정확히 공유하는 사례 ${w?.records.length||0}개. 다른 탐색 기간과도 겹칩니다. 패킷이 달라도 독립 표본을 뜻하지 않습니다.</p><details><summary>기간별 사례 수와 중복 확인</summary>${graph.windows.map(w=>`<p>${w.phase==='discovery'?'탐색':'확인'} ${period(w)} · ${w.records.length}개 사례</p>`).join('')}<small>달력 구간의 정확한 일치·겹침만 계산합니다. 행 단위 표본 동일성이나 독립성을 추정하지 않습니다.</small></details></div></div><aside class="rm-detail" aria-label="선택 노드 상세" aria-live="polite">${detail(r)}</aside></div>`;}
function registrationStatus(r){const l=r.registered_lineage;if(!l)return '<h4>등록 시 지식·교훈 참조 기록</h4><p class="rm-callout">NOT_RECORDED · 이 실험에는 등록 시 지식 스냅샷과 참조 선언이 기록되지 않았습니다. 원문에서 확인한 교훈 인용과 구분하며 소급 채우지 않습니다.</p>';if(l.status!=='RECORDED_AT_REGISTRATION')return '<h4>등록 시 지식·교훈 참조 기록</h4><p class="rm-callout">WITHHELD · 보존된 등록 계보의 인증을 완료하지 못해 연결 근거로 사용하지 않습니다.</p>';return `<h4>등록 시 지식·교훈 참조 기록</h4><p>등록 ${E(l.registered_at)} · 현재 공개 버전과 일치하는 참조 ${l.lesson_references.length}개 · 연결 보류 ${l.withheld_reference_count||0}개</p><p class="rm-callout">등록 전에 선언한 참조입니다. 실제 읽기·인과 영향·독립 검증·후속 질문 실행을 입증하지 않습니다.</p><code>snapshot ${E(l.knowledge_snapshot_hash)}</code>`;}
function detail(r){const p=projected();if(state.evidence)return evidenceDetail(r,p);const key=state.node;let body='';
 if(key==='hypothesis')body=lines(r.definition.hypothesis)+`<h4>기대 관계와 경제적 설명</h4>`+lines(r.definition.mechanism)+`<h4>선언된 추가 재무입력 (Factor.needs)</h4>${Array.isArray(r.definition.inputs)?(r.definition.inputs.length?`<p>${E(r.definition.inputs.join(' · '))}</p>`:'<p class="rm-callout">선언된 추가 재무입력 없음 · 공통 시장입력은 별도입니다. 빈 needs는 가격·거래량을 사용하지 않았다는 뜻이 아닙니다.</p>'):'<p class="rm-callout">추가 재무입력 선언 미기록 · 현재 코드로 소급 채우지 않습니다.</p>'}<code>/records/${catalog.records.findIndex(x=>x.record_id===r.record_id)}/definition/inputs</code><h4>입력 해석의 조건</h4>`+lines(r.definition.data_notes)+registrationStatus(r);
 if(key==='lesson')body=lines(r.review.general_lesson)+`<h4>해석의 범위</h4>`+lines(r.review.scope)+`<p>${badge(r.review.stance)} 는 이 교훈에 대한 검토 입장입니다. 메커니즘 입증이나 투자 수익성 판정이 아닙니다.</p>`+methodology(r,p);
 if(key==='observations')body=metrics(r)+r.review.observations.map(o=>`<article class="rm-detail-item">${lines(o.text)}${refs(r,o.evidence_ids,'인용 근거')}</article>`).join('');
 if(key==='explanations')body=`<p class="rm-callout">사후 검토의 경쟁 설명입니다. 아래 지지·제약 관계는 원문의 supporting/opposing evidence 필드만 옮겼습니다.</p>`+r.review.explanations.map(e=>`<article class="rm-detail-item"><h4>${E(e.claim)}</h4>${badge(e.status)}${refs(r,e.supporting_evidence,'원문 지지')}${refs(r,e.opposing_evidence,'원문 제약')}<p><b>구분하려면</b> ${E(e.distinguishing_observation)}</p></article>`).join('');
 if(key==='limits')body=`<p class="rm-callout">미수집 ≠ 실패. 과거 패킷은 불변입니다. raw-input-profile-v2가 이후 수정됐어도 이 실행의 빈 raw_input_profile을 소급 채우지 않습니다.</p>`+r.review.unresolved.map(t=>`<article class="rm-detail-item">${lines(t)}</article>`).join('')+`<h4>당시 진단의 수집 상태</h4>`+Object.entries(r.diagnostics).map(([k,v])=>`<p>${E(k)} ${badge(v.status)}</p>`).join('')+`<p><a href="${url('research/REGIME_REMEDIATION_20260923.md')}" target="_blank" rel="noopener">후속 입력 진단 수정 기록 ↗</a></p>`;
 if(key==='followup')body=`<p class="rm-callout">제안 · 미실행 / PROPOSED_NOT_RUN<br>필요 입력의 현재 가용성은 이 스냅샷에서 확인하지 않았습니다.</p>`+lines(r.review.follow_up.question)+`<h4>구분하려는 설명</h4><p>${E(r.review.follow_up.distinguishes.join(' · '))}</p><h4>필요한 자료와 제약</h4>`+lines(r.review.follow_up.data_needed)+`<p>이 질문은 연구 검토용입니다. 다음 후보 생성 에이전트에 자동 전달하지 않습니다.</p>`;
 const sourceNode=nodeFor(p.sections[key]);return `<span class="rm-eyebrow">${sectionTypes[key]}</span><h3>${sectionTitles[key]}</h3>${body}${source(r,sourceNode.source.pointer)}`;
}
function methodology(r,p){const links=graph.edges.filter(e=>e.relation==='methodology_reference'&&(e.from===p.sections.lesson||e.to===p.sections.hypothesis));return links.length?`<h4>다른 연구와 명시적으로 이어진 교훈</h4>${links.map(e=>{const other=graph.records.find(x=>x.sections.lesson===e.from),to=graph.records.find(x=>x.sections.hypothesis===e.to),target=other.id===r.record_id?to:other;return `<button class="rm-cross-link" data-rm-record="${E(target.id)}">${E(name(catalog.records.find(r=>r.record_id===target.id)))} ↗</button><p>${e.registration?'등록 시 선언한 교훈 활용 · 보존한 참조 버전 인증.':'방법론 교훈 활용 · data_notes의 정확한 lesson_key 인용.'} 앞 연구가 뒤 가설을 실증적으로 지지한다는 뜻은 아닙니다.</p>`;}).join('')}`:'';}
function metrics(r){const d=r.performance.discovery,c=r.performance.confirmation,m=c?.metrics||{};return `<div class="rm-metrics"><div><small>탐색 Rank IC</small><b>${F(d?.metrics?.ic_investable)}</b><small>${period(d?.discovery_signal_period)}</small></div><div><small>확인 OOS Rank IC</small><b>${F(m.oos_ic)}</b><small>${period(c?.oos_signal_period)}</small></div>${typeof m.net==='number'?`<div><small>탐색 비용 후 연환산 초과수익</small><b>${F(m.net,2)}%p</b><small>탐색 구간 · OOS 수익 아님</small></div>`:''}</div><p class="rm-callout">PROMOTE ≠ 메커니즘 입증 ≠ 비용 후 수익성. 같은 과거 구간의 확인 결과는 새로운 독립 재현으로 세지 않습니다.</p>`;}
function evidenceDetail(r,p){const n=nodeFor(p.evidence[state.evidence]);if(!n)return '<p>연결된 근거가 없습니다.</p>';const value=pointer(r,n.source.pointer),status=value?.status;return `<button class="rm-back" data-rm-node="${state.node}">← ${sectionTitles[state.node]}로</button><span class="rm-eyebrow">원문 근거 · 패킷 내 식별자</span><h3>${E(n.label)}</h3><code>${E(state.evidence)}</code>${status?badge(status):''}<p class="rm-callout">${state.evidence==='hypothesis'?'선언된 가설 자체는 관측 사실이 아닙니다.':'근거를 인용했다는 사실이 해당 설명을 입증하지는 않습니다.'}</p>${state.evidence.endsWith('.metrics')?metrics(r):''}<details class="rm-source" open><summary>기록된 값</summary><pre>${E(JSON.stringify(value,null,2))}</pre></details>${source(r,n.source.pointer)}<p>근거 ID는 <code>packet hash + evidence ID</code>로 구분합니다. 동일 ID 문자열을 서로 다른 연구의 동일 관측으로 합치지 않습니다.</p>`;}
function render(c,h,onChange){catalog=c;helpers=h;rerender=onChange;
 if(!graph)return `<section class="panel"><h1>연구 지도</h1><p>${failure?'지도를 불러오지 못했습니다. 기존 교훈·연구 상세는 계속 볼 수 있습니다.':'인증된 연구 연결을 불러오는 중입니다.'}</p><a href="#lessons">레슨 런 보기 ↗</a></section>`;
 if(graph.records.some(p=>!catalog.records.some(r=>r.record_id===p.id&&r.provenance.packet_sha256===p.packet&&r.provenance.review_basis===p.review_basis&&r.review_status==='REVIEWED_CURRENT')))return '<section class="panel"><h1>스냅샷 불일치</h1><p>카탈로그와 지도를 함께 재생성해야 합니다. 오래된 연결을 표시하지 않습니다.</p></section>';
 if(graph.network&&window.ResearchNetworkUI)return window.ResearchNetworkUI.render(graph,catalog,helpers,{update:rerender,detail:(r,section,evidence)=>{state.record=r.record_id;state.node=section;state.evidence=evidence;return detail(r);}});
 chooseFirst();const r=selected();return `<div class="rm-page"><header class="rm-heading"><div><span class="rm-eyebrow">RESEARCH ATLAS / 검토된 지식의 지도</span><h1>교훈을 쌓고,<br><em>다음 질문을 연결합니다.</em></h1><p>무엇을 만들었고, 무엇을 보았고, 무엇을 아직 모르는가.</p></div><div class="rm-stats"><span><b>${graph.counts.included}</b>검토 사례</span><span><b>${graph.counts.campaigns}</b>공개 캠페인</span><span><b>${graph.counts.withheld}</b>봉인 · 내용 제외</span></div></header><div class="rm-snapshot"><span class="rm-dot"></span>${E(graph.as_of)} 정적 스냅샷 · ${E(graph.mapping_version)}<span>관계선은 인과관계의 증명이 아닙니다</span></div>${themeGraph()}${overview()}${r?focusGraph(r):'<div class="rm-empty">조건에 맞는 교훈이 없습니다. 검색어나 판단 필터를 바꿔 주세요.</div>'}<details class="rm-contract"><summary>이 지도의 범위 · 연결 규칙 · 재생성 출처</summary><p>기존 인증 exporter가 release 상태·패킷 재구성·review binding을 검증한 카탈로그 뒤에 붙는 projection입니다. ${graph.counts.included}개 현재 검토만 포함, 오래되거나 비공개인 입력 ${graph.counts.omitted_not_current}개 제외, 봉인 ${graph.counts.withheld}개는 내용 미포함. ${graph.counts.lessons}개 서로 다른 lesson_key를 임의 병합하지 않았습니다.</p><p>주제선 about은 버전 관리된 편집 분류입니다. 구조선은 같은 검토의 항목 연결입니다. 실증적 지지/제약은 원문 explanations의 evidence 참조만 표시합니다. 텍스트 유사도, 자동 의미 추론, 임의 갈등선은 없습니다. 서로 다른 가설의 SUPPORTS·UNCERTAIN을 합쳐 하나의 결론을 만들지 않습니다.</p><p>현재 raw_input_profile 공백은 당시 미수집입니다. 이후 수정과 구분합니다. 이 사이트는 연구 검토용이며 OOS 수치·후속 질문을 후보 생성 입력으로 내보내는 기능은 없습니다. 공개문헌을 독립적인 로컬 재현으로 세지 않습니다.</p><code>catalog SHA-256 ${E(graph.catalog_sha256)}<br>source revision ${E(graph.revision)}</code><p><a href="./data/research-map.json" target="_blank" rel="noopener">구조화된 지도 스냅샷 ↗</a> · <a href="#method">기존 근거와 방법론 ↗</a></p></details></div>`;
}
function update(focus){rerender?.();if(focus)document.querySelector(focus)?.focus({preventScroll:true});}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.rmTheme){state.theme=b.dataset.rmTheme;state.filter='ALL';state.evidence=null;update(`[data-rm-theme="${state.theme}"]`);}else if(b.dataset.rmNode){state.node=b.dataset.rmNode;state.evidence=null;update(`[data-rm-node="${state.node}"]`);}else if(b.dataset.rmEvidence){state.evidence=b.dataset.rmEvidence;update('.rm-back');}else if(b.dataset.rmRecord){state.record=b.dataset.rmRecord;state.query='';state.filter='ALL';state.evidence=null;update('#rm-case');}else if(b.hasAttribute('data-rm-prev')||b.hasAttribute('data-rm-next')){const rows=eligible(),i=rows.findIndex(r=>r.record_id===state.record),delta=b.hasAttribute('data-rm-prev')?-1:1;state.record=rows[i+delta]?.record_id||state.record;state.evidence=null;update(b.hasAttribute('data-rm-prev')?'[data-rm-prev]':'[data-rm-next]');}});
document.addEventListener('change',e=>{if(e.target.id==='rm-case'){state.record=e.target.value;state.evidence=null;update('#rm-case');}if(e.target.id==='rm-filter'){state.filter=e.target.value;state.evidence=null;update('#rm-filter');}});
document.addEventListener('input',e=>{if(e.target.id!=='rm-search')return;state.query=e.target.value;state.evidence=null;update('#rm-search');});
window.ResearchMapUI={render};
fetch('./data/research-map.json').then(r=>{if(!r.ok)throw Error('Map unavailable');return r.json();}).then(g=>{if(g.schema_version!=='reviewer-research-map-v1')throw Error('Unsupported map');graph=g;window.dispatchEvent(new Event('research-map-ready'));}).catch(()=>{failure=true;window.dispatchEvent(new Event('research-map-ready'));});
})();
